// --- ADJUST THRESHOLD ---
const LOW_STOCK_THRESHOLD = 10;
// -------------------------

const ordersData = $('Get Yesterday\'s Orders').first().json.orders || [];
const productsData = $('Get Inventory Levels').first().json.products || [];
const adsData = $('Get Ad Insights').first().json.data || [];

// --- Sales summary ---
let totalRevenue = 0;
const productSales = {};
for (const o of ordersData) {
  totalRevenue += parseFloat(o.total_price || 0);
  for (const li of (o.line_items || [])) {
    productSales[li.title] = (productSales[li.title] || 0) + li.quantity;
  }
}
const topProducts = Object.entries(productSales)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([title, qty]) => ({ title, qty }));

// --- Low stock ---
const lowStock = [];
for (const p of productsData) {
  for (const v of (p.variants || [])) {
    if (v.inventory_quantity !== undefined && v.inventory_quantity <= LOW_STOCK_THRESHOLD) {
      lowStock.push({ product: p.title, variant: v.title, quantity: v.inventory_quantity });
    }
  }
}

// --- Ads summary ---
let totalSpend = 0;
const campaigns = adsData.map(c => {
  totalSpend += parseFloat(c.spend || 0);
  return {
    name: c.campaign_name,
    spend: c.spend,
    ctr: c.ctr,
    cpc: c.cpc
  };
});

return [{
  json: {
    date: new Date().toISOString().slice(0, 10),
    sales: {
      order_count: ordersData.length,
      total_revenue: Math.round(totalRevenue * 100) / 100,
      top_products: topProducts
    },
    inventory: {
      low_stock_items: lowStock,
      low_stock_count: lowStock.length
    },
    ads: {
      total_spend: Math.round(totalSpend * 100) / 100,
      campaigns
    }
  }
}];

