const raw = $input.first().json.content[0].text;
const cleaned = raw.replace(/```json|```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    state_of_business: 'Could not generate briefing — check raw data manually.',
    whats_working: '',
    needs_attention: '',
    todays_actions: ''
  };
}

const body = `STATE OF THE BUSINESS\n${parsed.state_of_business}\n\nWHAT'S WORKING\n${parsed.whats_working}\n\nNEEDS ATTENTION\n${parsed.needs_attention}\n\nTODAY'S 3 ACTIONS\n${parsed.todays_actions}`;

return [{ json: { ...parsed, email_body: body } }];
